param([string]$BuildRoot='build/t475-s5/p8-guard')
$ErrorActionPreference='Stop';$repo=(Resolve-Path "$PSScriptRoot/../..").Path;$build=[IO.Path]::GetFullPath($BuildRoot,$repo);if(Test-Path $build){throw 'Fresh build root required'};New-Item -ItemType Directory -Path $build|Out-Null
foreach($variant in @('win101','win31')) {
 $dir=Join-Path $build $variant;$owned=Join-Path $dir 'owned';$other=Join-Path $dir 'other';$shadow=$owned+'-shadow';New-Item -ItemType Directory -Force $owned,$other,$shadow|Out-Null;[IO.File]::WriteAllText((Join-Path $other 'outside.txt'),'x');[IO.File]::WriteAllText((Join-Path $shadow 'shadow.txt'),'s')
 & "$repo/tools/build-fixtures.cmd" x86 "observer-guard-$variant" *> "$build/$variant-build.stdout"
 if($LASTEXITCODE){throw "Guard fixture build failed"}
 $old=@($env:WIN101_GUARD_ROOT,$env:WIN101_GUARD_TARGET,$env:WIN101_GUARD_STAGE,$env:WIN101_GUARD_MEDIA);try {$env:WIN101_GUARD_ROOT=$owned;$env:WIN101_GUARD_TARGET='';$env:WIN101_GUARD_STAGE='';$env:WIN101_GUARD_MEDIA='';$p=Start-Process "$repo/build/.ninja/fixtures-x86/observer-guard-$variant.exe" -ArgumentList @('"'+$owned+'"','"'+$other+'"','"'+$shadow+'"') -WorkingDirectory $dir -RedirectStandardOutput "$owned/result.stdout" -RedirectStandardError "$owned/result.stderr" -WindowStyle Hidden -PassThru;"pid=$($p.Id)"|Set-Content "$build/$variant.process";if(!$p.WaitForExit(60000)){taskkill /PID $p.Id /T /F;throw 'run timeout'};$p.Refresh();"exit=$($p.ExitCode)"|Add-Content "$build/$variant.process";if($p.ExitCode){throw "$variant test failed"};if((Get-Content -Raw "$owned/result.stdout") -notmatch 'PASS real guard'){throw "$variant missing fixture pass"};$log=Get-Content -Raw -Encoding Unicode "$owned/install-writes.txt";foreach($marker in @('ALLOW create','ALLOW write','DENY create','ALLOW readonly-open-no-create','DENY set-info')){if(!$log.Contains($marker)){throw "$variant missing $marker"}};if((Get-Content -Raw "$other/outside.txt") -ne 'x' -or (Get-Content -Raw "$shadow/shadow.txt") -ne 's' -or (Test-Path "$other/missing.txt") -or (Test-Path "$other/escaped.txt")){throw "$variant external mutation"}; $env:WIN101_GUARD_TARGET=$other
 $p=Start-Process "$repo/build/.ninja/fixtures-x86/observer-guard-$variant.exe" -ArgumentList @('"'+$owned+'"','"'+$other+'"','"'+$shadow+'"') -WorkingDirectory $dir -RedirectStandardOutput "$build/$variant-reject.stdout" -RedirectStandardError "$build/$variant-reject.stderr" -WindowStyle Hidden -PassThru
 "pid=$($p.Id)"|Set-Content "$build/$variant-reject.process";if(!$p.WaitForExit(60000)){taskkill /PID $p.Id /T /F;throw 'reject timeout'};$p.Refresh();"exit=$($p.ExitCode)"|Add-Content "$build/$variant-reject.process";if($p.ExitCode -ne 127){throw "$variant accepted unapproved target"}
 }finally{$env:WIN101_GUARD_ROOT=$old[0];$env:WIN101_GUARD_TARGET=$old[1];$env:WIN101_GUARD_STAGE=$old[2];$env:WIN101_GUARD_MEDIA=$old[3]}
}
'PASS Win101 and Win31 C restricted-write guards'
